#!/bin/sh
# Generated by frostfire. MariaDB entrypoint for FreeBSD, doing what the official
# Linux image does: initialize an empty datadir with MARIADB_ROOT_PASSWORD, run
# mariadb-upgrade after version changes, and shut down cleanly when stopped.
set -eu

: "${MARIADB_ROOT_PASSWORD:?MARIADB_ROOT_PASSWORD is required}"

datadir=/var/db/mysql
extra=/frostfire/mariadb/frostfire.cnf

server=
for c in /usr/local/libexec/mariadbd /usr/local/libexec/mysqld; do
    if [ -x "$c" ]; then server=$c; break; fi
done
[ -n "$server" ] || { echo "frostfire: mariadbd not found" >&2; exit 1; }

mkdir -p "$datadir" /var/run/mysql
chown mysql:mysql "$datadir" /var/run/mysql

# --defaults-extra-file has to be the first option.
set --
[ -f "$extra" ] && set -- "--defaults-extra-file=$extra"
set -- "$@" --user=mysql --datadir="$datadir" --skip-name-resolve

wait_up() {
    i=0
    until mariadb-admin --silent ping >/dev/null 2>&1; do
        kill -0 "$1" 2>/dev/null || { echo "frostfire: mariadbd exited during startup" >&2; exit 1; }
        i=$((i + 1))
        [ "$i" -gt 120 ] && { echo "frostfire: mariadbd did not start within 2 minutes" >&2; exit 1; }
        sleep 1
    done
}

if [ ! -d "$datadir/mysql" ]; then
    echo "frostfire: initializing a new database"
    mariadb-install-db --user=mysql --datadir="$datadir" \
        --auth-root-authentication-method=normal --skip-test-db >/dev/null

    "$server" "$@" --skip-networking &
    pid=$!
    wait_up "$pid"

    # Escape for a single-quoted SQL string.
    pw=$(printf '%s' "$MARIADB_ROOT_PASSWORD" | sed -e 's/\\/\\\\/g' -e "s/'/''/g")
    mariadb -uroot <<SQL
ALTER USER 'root'@'localhost' IDENTIFIED BY '${pw}';
CREATE USER IF NOT EXISTS 'root'@'%' IDENTIFIED BY '${pw}';
GRANT ALL PRIVILEGES ON *.* TO 'root'@'%' WITH GRANT OPTION;
DROP USER IF EXISTS ''@'localhost';
FLUSH PRIVILEGES;
SQL
    MYSQL_PWD="$MARIADB_ROOT_PASSWORD" mariadb-admin -uroot shutdown
    wait "$pid" || true
fi

export MYSQL_PWD="$MARIADB_ROOT_PASSWORD"

"$server" "$@" --bind-address=0.0.0.0 &
pid=$!
trap 'kill -TERM "$pid" 2>/dev/null' TERM INT
wait_up "$pid"

# No-op unless the data was written by an older MariaDB (e.g. a restored backup).
mariadb-upgrade -uroot --silent >/dev/null 2>&1 || echo "frostfire: mariadb-upgrade reported a problem" >&2

set +e
wait "$pid"
status=$?
if kill -0 "$pid" 2>/dev/null; then
    wait "$pid"
    status=$?
fi
exit "$status"
